-- Expanded Psionics Handbook powers N-P.
-- Concise mechanical summaries; XPH remains the source of record.

WITH desired(slug,name,discipline,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,description,augmentation_text) AS (VALUES
('null-psionics-field','Null Psionics Field','psychokinesis',NULL,'1 standard action','standard','10 ft.',NULL,'10-ft.-radius emanation centered on you',NULL,'10 min./level (D)',NULL,'None','conditional','See text',11,'Create a mobile field that suppresses most psionic powers, psi-like abilities, supernatural psionic abilities, and psionic items within its area without normally dispelling them.',NULL),
('oak-body','Oak Body','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,9,'Transform into living oak, gaining DR 10/slashing, natural armor, broad physiological immunities, Strength, and other benefits while taking the listed movement and fire-related drawbacks.','Psion/wilder base cost is 13 PP; psychic warrior base cost is 9 PP. Each additional PP extends duration by 1 minute.'),
('object-reading','Object Reading','clairsentience',NULL,'1 minute','other','Touch','Object touched',NULL,NULL,'Concentration, up to 10 min./level (D)',NULL,'None','yes',NULL,3,'Read psychic impressions from an inanimate object to learn progressively more information about previous owners while concentrating.','Each additional PP increases maximum duration by 10 minutes.'),
('overland-flight-psionic','Overland Flight, Psionic','psychoportation',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 hour/level (D)',NULL,NULL,'no',NULL,11,'Gain the effects of the overland flight spell psionically.',NULL),
('painful-strike','Painful Strike','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'no',NULL,3,'Cause each successful natural-weapon attack to deal an extra 1d6 nonlethal damage.','Spend 6 additional PP to manifest as a swift action.'),
('personality-parasite','Personality Parasite','telepathy',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','One Medium or smaller humanoid',NULL,NULL,'1 round/level (D)','will','Will negates','yes',NULL,7,'Partition the target’s mind to create an antagonistic secondary personality that takes one purely mental standard action each round using the subject’s own lower-level powers and reserve.',NULL),
('phase-door-psionic','Phase Door, Psionic','psychoportation',NULL,'1 standard action','standard','0 ft.',NULL,NULL,'Ethereal 5-ft. by 8-ft. opening, 10 ft. deep + 5 ft. per three levels','One usage per two levels',NULL,'None','no',NULL,13,'Create an ethereal passage as the phase door spell, subject to dispel psionics.',NULL),
('plane-shift-psionic','Plane Shift, Psionic','psychoportation',NULL,'1 standard action','standard','Touch','One willing creature or up to eight willing creatures joining hands',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,9,'Transport willing travelers between planes as the plane shift spell.',NULL),
('power-leech','Power Leech','telepathy','compulsion','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One psionic creature',NULL,NULL,'Concentration, up to 1 round/level; see text','will','Will negates','yes',NULL,7,'Drain 1d6 power points from the subject each round you maintain full-round concentration, adding 1 drained point per round to your own reserve when possible.',NULL),
('power-resistance','Power Resistance','clairsentience',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'1 min./level','will','Will negates (harmless)','yes','Yes (harmless)',9,'Grant the touched creature power resistance equal to 12 + your manifester level.',NULL),
('precognition','Precognition','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'no',NULL,1,'Gain one precognitive edge that can be spent within the duration for a +2 insight bonus on one attack roll, damage roll, saving throw, or skill check.',NULL),
('precognition-defensive','Precognition, Defensive','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,1,'Gain a +1 insight bonus to Armor Class and saving throws while you retain the Dexterity-dependent benefit described by the power.','Every 3 additional PP increases the insight bonus by 1; spend 6 additional PP to manifest as a swift action.'),
('precognition-greater','Precognition, Greater','clairsentience',NULL,'10 minutes','other','Personal','You',NULL,NULL,'1 hour/level',NULL,NULL,'no',NULL,11,'As precognition, but the precognitive edge provides a +4 insight bonus and lasts up to 1 hour per level.',NULL),
('precognition-offensive','Precognition, Offensive','clairsentience',NULL,'1 standard action; see text','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,1,'Gain a +1 insight bonus on attack rolls.','Every 3 additional PP increases the attack bonus by 1; spend 6 additional PP to manifest as a swift action.'),
('prescience-offensive','Prescience, Offensive','clairsentience',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 min./level (D)',NULL,NULL,'no',NULL,1,'Gain a +2 insight bonus on damage rolls.','Every 3 additional PP increases the damage bonus by 1; spend 6 additional PP to manifest as a swift action.'),
('prevenom','Prevenom','psychometabolism','creation','1 standard action','standard','Personal','You',NULL,NULL,'1 min./level or until discharged',NULL,NULL,'no',NULL,1,'Coat one qualifying claw with venom so the next successful melee attack can deal 2 Constitution damage unless the victim succeeds on the power-defined Fortitude save.','Every 6 additional PP increases Constitution damage by 2.'),
('prevenom-weapon','Prevenom Weapon','psychometabolism','creation','1 standard action','standard','Touch','Weapon touched',NULL,NULL,'1 min./level or until discharged',NULL,NULL,'no',NULL,1,'As prevenom, except the poison coating is placed on a weapon you keep in your grip.',NULL),
('prowess','Prowess','clairsentience',NULL,'1 immediate action','immediate','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,3,'Immediately make an attack of opportunity when one is provoked even if you have already used your normal allotment for the round.',NULL),
('psionic-blast','Psionic Blast','telepathy',NULL,'1 standard action','standard','30 ft.',NULL,'30-ft. cone-shaped burst',NULL,'Instantaneous','will','Will negates','yes',NULL,5,'Blast creatures in the cone with mental force, stunning affected targets for 1 round.','Every 2 additional PP increases stun duration by 1 round.'),
('psionic-lions-charge','Psionic Lion''s Charge','psychometabolism',NULL,'1 swift action','swift','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'no',NULL,3,'Gain the ability to make a full attack as part of your charge in the current round.','Each additional PP gives every attack after the charge a circumstance damage bonus equal to the additional PP spent.'),
('psionic-lock','Psionic Lock','psychoportation',NULL,'1 standard action','standard','Touch','Door, chest, or portal touched, up to 30 sq. ft./level',NULL,NULL,'Permanent',NULL,'None','no',NULL,3,'Psionically lock a door, chest, or portal, increasing the break DC and requiring appropriate dispelling or forced entry for others.',NULL),
('psionic-repair-damage','Psionic Repair Damage','metacreativity',NULL,'1 standard action','standard','Touch','Construct touched',NULL,NULL,'Instantaneous','will','Will negates (harmless)','yes','Yes (harmless)',3,'Repair 3d8 +1 per manifester level hit points of damage to a construct that still has at least 1 hit point.','Every 2 additional PP repairs another 1d8 damage.'),
('psionic-revivify','Psionic Revivify','psychometabolism','healing','1 standard action','standard','Touch','Dead creature touched',NULL,NULL,'Instantaneous',NULL,'None','yes','Yes (harmless)',9,'Reconnect a recently dead creature’s psyche to its body within 1 round of death, restoring it without the normal level or Constitution loss and leaving it stable at –1 hit points.','XP cost: 200 XP; additional shared XP can extend the allowable delay one round per 100 XP each.'),
('psionic-scent','Psionic Scent','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'no',NULL,3,'Gain the scent ability, including detecting, locating, and tracking creatures by smell using the ranges and modifiers defined by the power.',NULL),
('psychic-chirurgery','Psychic Chirurgery','telepathy',NULL,'10 minutes','other','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','will','Will negates','yes',NULL,17,'Repair severe psychic harm, remove many lasting mental and level-related effects, or directly transfer knowledge of a power you know to another psionic character.','Transferring power knowledge costs 1,000 XP × power level, optionally split with a willing subject.'),
('psychic-crush','Psychic Crush','telepathy',NULL,'1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','will','Will partial; see text','yes',NULL,9,'Crush a creature’s mental essence; a failed Will save causes collapse unconscious and dying at –1 hit points, while a successful save deals 3d6 damage.','Every 2 additional PP increases successful-save damage by 1d6.'),
('psychic-reformation','Psychic Reformation','telepathy',NULL,'10 minutes','other','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous',NULL,'None','no',NULL,7,'Let the subject revise recent skill-point, feat, and power-known choices, with deeper revisions reaching back additional levels at increasing XP cost.','XP cost starts at 50 XP for current-level choices and increases by 50 XP per additional prior level; manifester and subject split the cost.'),
('psychic-vampire','Psychic Vampire','psychometabolism',NULL,'1 standard action','standard','Touch','Creature touched',NULL,NULL,'Instantaneous','fort','Fortitude negates','yes',NULL,7,'Charge your hand or a natural weapon to drain 2 power points per manifester level from a psionic target, or deal mental ability damage to a target without power points.','Egoist and psychic warrior both use the 4th-level, 7-PP version.'),
('psychofeedback','Psychofeedback','psychometabolism',NULL,'1 standard action','standard','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'no',NULL,9,'Boost one physical ability score by burning points from one or more other physical ability scores; the boost ends with the power but ability burn heals only naturally.',NULL)
)
INSERT INTO dnd35_powers
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,augmentation_text,augmentation)
SELECT
  'xph-power-'||d.slug,'xph-3.5','Chapter 5',d.slug,d.name,d.description,d.description,0,NULL,1,
  'xph-power-discipline-'||d.discipline,d.subdiscipline,d.manifesting_time,d.action_type,d.range_text,
  d.target_text,d.area_text,d.effect_text,d.duration_text,d.save,d.saving_throw_text,
  d.power_resistance,d.power_resistance_text,d.power_points,d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_powers p
  WHERE p.slug=d.slug AND p.owner_user_id IS NULL
);
